class Battle::AI::AIMove
  attr_reader :move

  def initialize(ai)
    @ai = ai
  end

  def set_up(move)
    @move = move
    @move.calcType = rough_type
    @ai.battle.moldBreaker ||= ["IgnoreTargetAbility",
                                "CategoryDependsOnHigherDamageIgnoreTargetAbility"].include?(function_code)
  end

